package com.yeyamo_mobile.api.gamification_service.infrastructure.messaging;import java.util.UUID;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.gamification_service.application.GamificationService;
@Component public class GamificationEventConsumer{private final ObjectMapper mapper;private final EventXpPolicy policy;private final GamificationService service;private final ProcessedEventRepository processed;public GamificationEventConsumer(ObjectMapper m,EventXpPolicy p,GamificationService s,ProcessedEventRepository r){mapper=m;policy=p;service=s;processed=r;}@KafkaListener(topics={"${yeyamo.kafka.topics.user-events:user.events}","${yeyamo.kafka.topics.legacy-user-events:user-events}","${yeyamo.kafka.topics.content-events:content.events}","${yeyamo.kafka.topics.interaction-events:interaction.events}","${yeyamo.kafka.topics.booking-events:booking.events}"},groupId="${spring.kafka.consumer.group-id:gamification-service}")@Transactional public void consume(String raw)throws Exception{JsonNode e=mapper.readTree(raw);UUID id=UUID.fromString(required(e,"eventId"));if(processed.existsById(id))return;if(e.path("eventVersion").asInt(0)!=1)throw new IllegalArgumentException("Unsupported event version");String type=required(e,"eventType");policy.map(e).ifPresent(activity->service.apply(activity,text(e,"correlationId")));processed.save(new ProcessedEventEntity(id,type));}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}}
